import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"ADR 0004 — The runtime owns the moments that must be right","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0004-runtime-owned-steps.md","filePath":"reference/adr/0004-runtime-owned-steps.md"}`),a={name:`reference/adr/0004-runtime-owned-steps.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0004-—-the-runtime-owns-the-moments-that-must-be-right" tabindex="-1">ADR 0004 — The runtime owns the moments that must be right <a class="header-anchor" href="#adr-0004-—-the-runtime-owns-the-moments-that-must-be-right" aria-label="Permalink to “ADR 0004 — The runtime owns the moments that must be right”">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-10-02 → 2026-10-11 (eighteen journey items in the first vertical), restated 2026-10-13</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>With the whole journey model-led, measured over hundreds of chats: a required question was skipped 25–50% of the time depending on the run; a list published under the user&#39;s name was invented 1 in 64 chats even with a model-specific note; a model attested <code>confirmed:true</code> after the user sent a change; a correction was recorded without acknowledgement; a fetched record slid silently into the summary. Prompt rules moved these rates; none reached zero, and each model slipped somewhere else.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>The model owns the conversation; the runtime owns the moments that must be right. A <strong>step</strong> is such a moment: the runtime draws it (a form, chips, a picker), reads the reply in code by its whole content, writes the draft, carries the values into every tool call, and tells the model one fact. A settle chains into the next owed step or the confirmation summary in the same reply; an owed step is late-drawn under a model turn with the model&#39;s own question cut; words beside an open ask go to the model and the ask is redrawn under the answer; a reload redraws the open ask; the review re-opens a step&#39;s own card and returns to the summary; dependencies re-ask what a change invalidates. Steps are data on the manifest (per type) and code in the domain (<code>steps/index.ts</code>) built from three helpers or the raw interface.</p><h2 id="rejected" tabindex="-1">Rejected <a class="header-anchor" href="#rejected" aria-label="Permalink to “Rejected”">​</a></h2><ul><li>&quot;Stricter prompts&quot;: measured, insufficient, model-specific.</li><li>&quot;Validate after the fact only&quot;: the wrong value had already been shown and confirmed.</li><li>&quot;A form instead of a chat&quot;: loses the conversational gathering that the model does well.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Runtime turns cost no tokens and are deterministic — evals pin them exactly; the model&#39;s prompt gets a short block of runtime facts per turn (cache-stable prefix, varying tail); every step reports a behaviour event (counts and enums only). The eval runner must answer runtime asks it did not script (it does: <code>tap</code>, <code>submitForm</code>).</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0004-runtime-owned-steps.md">docs/adr/0004-runtime-owned-steps.md</a> — edit it there; the site mirrors the repository.</small></p>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};